COPY dist&#x2F; &#x2F;usr&#x2F;share&#x2F;nginx&#x2F;html&#x2F;
COPY nginx&#x2F;nginx-dev.conf &#x2F;etc&#x2F;nginx&#x2F;nginx.conf
EXPOSE 80
3.编写Jenkinsfile，放在项目根目录下
&#x2F;&#x2F;流水线脚本
pipeline &#123;
    agent any
    environment &#123;
        WS &#x3D; &quot;$&#123;WORKSPACE&#125;&quot;
        TOPIC &#x3D; &quot;测试&quot;
        TITLE &#x3D; &quot;标题&quot;
        CONTENT &#x3D; &quot;具体内容&quot;
    &#125;

    &#x2F;&#x2F;定义流水线的加工流程
    stages &#123;
        stage(&#39;环境检查&#39;) &#123;
            steps&#123;
                sh &#39;printenv&#39;
                echo &quot;正在检测基本信息&quot;
