                sh &#39;docker version&#39;
                sh &quot;echo 默认的项目目录:$&#123;WS&#125;&quot;
                sh &#39;cd $&#123;WS&#125;&#x2F;fast-ui &amp;&amp; docker build -t home-finance-web .&#39;
            &#125;
        &#125;

        stage(&#39;部署&#39;) &#123;
            steps&#123;
                echo &#39;部署....&#39;
                sh &#39;pwd &amp;&amp; ls -alh&#39;
                sh &#39;pwd &amp;&amp; ls -alh&#39;
                sh &#39;docker rm -f home-finance-web&#39;
                sh &#39;docker run -d -p 8081:80 --restart&#x3D;always --name home-finance-web home-finance-web&#39;
            &#125;
        &#125;
    &#125;
&#125;
