&lt;script&gt;
  function switchNightMode() &#123;
    $(&#39;&lt;div class&#x3D;&quot;Cuteen_DarkSky&quot;&gt;&lt;div class&#x3D;&quot;Cuteen_DarkPlanet&quot;&gt;&lt;&#x2F;div&gt;&lt;&#x2F;div&gt;&#39;).appendTo($(&#39;body&#39;)),
      setTimeout(function () &#123;
        $(&#39;body&#39;).hasClass(&#39;DarkMode&#39;) 
